const maxStr = (str, limit = 600) => {
  if (!str) return '';
  if (str.length <= limit) return str;
  return str.substring(0, limit) + '... [TRUNCATED]';
};

const inputJson = $input.first().json.data || {};
const digestRows = inputJson.digest_summary || [];
const personsRows = inputJson.new_persons || [];
const activitiesRows = inputJson.recent_activities || [];
const leadsRows = inputJson.high_priority_leads || [];

let text = 'CDB WEEKLY NETWORK REVIEW & PROSPECT PIPELINE FOR DON JIMMY\n\n';

// Section 1 (PRIORITY #1): Weekly Network Digest Summary (from sum_cdp_weekly_network_digest)
text += '=== SECTION 1: WEEKLY NETWORK DIGEST & CUMULATIVE STATS (PRIORITY SUMMARY) ===\n';
if (digestRows.length === 0) {
  text += 'No network digest records found in sum_cdp_weekly_network_digest.\n\n';
} else {
  const latest = digestRows[0] || {};
  text += `Latest Cumulative Network Totals:\n`;
  text += `- Total Leads: ${latest.total_leads_cumulative || 0}\n`;
  text += `- Total Persons/Contacts: ${latest.total_persons_cumulative || 0}\n`;
  text += `- Total Companies: ${latest.total_companies_cumulative || 0}\n`;
  text += `- Total Activities: ${latest.total_activities_cumulative || 0}\n\n`;
  text += `Daily Performance Breakdown (Last 14 Days):\n`;
  digestRows.forEach(row => {
    text += `- Date: ${row.date_berlin} | New Leads: ${row.new_leads_count || 0} | High Signal Leads: ${row.high_signal_leads_count || 0} | Active Pipeline Leads: ${row.active_pipeline_leads_count || 0} | New Contacts: ${row.new_persons_count || 0} (LinkedIn: ${row.new_linkedin_connections_count || 0}, Substack: ${row.new_substack_subscribers_count || 0}) | Daily Activities: ${row.daily_activities_count || 0}\n`;
  });
  text += '\n';
}

// Section 2 (PRIORITY #2): New Persons & Associated Companies
text += '=== SECTION 2: NEW PERSONS & ASSOCIATED COMPANIES ===\n';
if (personsRows.length === 0) {
  text += 'No new persons/contacts recorded.\n\n';
} else {
  personsRows.forEach((p, idx) => {
    text += `[Person #${idx + 1}] ${p.full_name || 'N/A'} | Primary Company: ${p.primary_company_name || 'N/A'} | Temp: ${p.engagement_temperature || 'N/A'} | Segment: ${p.person_segment_name || 'N/A'} | Email: ${p.primary_email || 'N/A'} | LinkedIn: ${p.linkedin_url || 'N/A'} | Added: ${p.created_at_berlin || 'N/A'}\n`;
  });
  text += '\n';
}

// Section 3 (PRIORITY #3): Recent Activities & Outreach Events
text += '=== SECTION 3: RECENT ACTIVITIES & OUTREACH EVENTS ===\n';
if (activitiesRows.length === 0) {
  text += 'No recent activities recorded.\n\n';
} else {
  activitiesRows.forEach((act, idx) => {
    text += `[Activity #${idx + 1}] Title: ${act.title || 'N/A'} | Type: ${act.activity_type || 'N/A'} | Date: ${act.activity_date_berlin || 'N/A'}\n`;
    if (act.summary_or_content) text += `  Details: ${maxStr(act.summary_or_content, 300)}\n`;
    if (act.to_dos) text += `  To-Dos: ${maxStr(act.to_dos, 200)}\n`;
    text += '\n';
  });
}

// Section 4 (PRIORITY #4): Active Leads & Follow-up Context
text += '=== SECTION 4: ACTIVE HIGH-PRIORITY LEADS & CONTEXT ===\n';
if (leadsRows.length === 0) {
  text += 'No active high-priority leads.\n\n';
} else {
  leadsRows.forEach((lead, idx) => {
    text += `[Lead #${idx + 1}] Name: ${lead.full_name || 'N/A'} | Stage: ${lead.lead_stage_name || 'N/A'} | Signal: ${lead.signal_strength || 'N/A'} | Intent: ${lead.intent || 'N/A'} | Opportunity: ${lead.opportunity_type || 'N/A'} | Intake Date: ${lead.intake_at_berlin || 'N/A'}\n`;
    if (lead.description) text += `  Description: ${maxStr(lead.description, 300)}\n`;
    if (lead.summary) text += `  Summary: ${maxStr(lead.summary, 300)}\n`;
    text += '\n';
  });
}

const fs = require('fs');
let persona = '';
try {
  persona = fs.readFileSync('/etc/n8n/agents/bella.md', 'utf8');
} catch (e) {
  persona = 'You are Bella, Don Jimmy (Jimmy Pang)\'s charming, warm, and highly competent Italian assistant.';
}

const allContacts = [];
personsRows.forEach(p => { if (p.full_name && p.linkedin_url) allContacts.push({ full_name: p.full_name, linkedin_url: p.linkedin_url }); });
leadsRows.forEach(l => { if (l.full_name && l.linkedin_url) allContacts.push({ full_name: l.full_name, linkedin_url: l.linkedin_url }); });

return [{ json: { text: text.substring(0, 15000), bella_persona: persona, contacts_list: allContacts } }];

