const raw = $input.first().json.content || $input.first().json.response || '';
const contactsList = $('Format Data for Bella').first().json.contacts_list || [];

let jsonStr = raw.trim();
const firstBrace = jsonStr.indexOf('{');
const lastBrace = jsonStr.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  jsonStr = jsonStr.substring(firstBrace, lastBrace + 1);
}

jsonStr = jsonStr.replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"');

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  try {
    const cleanedStr = jsonStr.replace(/,\s*([}\]])/g, '$1');
    parsed = JSON.parse(cleanedStr);
  } catch (err) {
    return [{ json: { response: raw } }];
  }
}

const greeting = parsed.greeting || '';
const signoff = parsed.signoff || '';
const digestSummary = parsed.weekly_network_digest_summary || {};
const newPersons = parsed.new_persons_and_companies_highlights || {};
const activitiesReview = parsed.recent_activities_review || {};
const recommendedActions = Array.isArray(parsed.recommended_follow_up_actions) ? parsed.recommended_follow_up_actions : [];

function addSlackLinks(text) {
  let linkedText = text.replaceAll('**', '*');

  // 1. Clean up any malformed or double-wrapped Slack links generated by LLM
  linkedText = linkedText.replace(/<+([^|>]+)\|([^|>]+)>/g, (m, url, name) => {
    let cleanUrl = url.trim();
    if (!cleanUrl.startsWith('http://') && !cleanUrl.startsWith('https://')) {
      cleanUrl = 'https://' + cleanUrl;
    }
    let cleanName = name.replace(/^[|<]+/, '').replace(/[>]+$/, '').trim();
    return `<${cleanUrl}|${cleanName}>`;
  });

  // 2. Safely add Slack links for known contacts without double-wrapping
  contactsList.forEach(c => {
    if (c.full_name && c.linkedin_url) {
      let rawUrl = c.linkedin_url.trim();
      if (!rawUrl.startsWith('http://') && !rawUrl.startsWith('https://')) {
        rawUrl = 'https://' + rawUrl;
      }
      const fullName = c.full_name.trim();
      const escapedName = fullName.replace(/[-\/^$*+?.()|[\]{}]/g, '\\$&');
      const regex = new RegExp(escapedName, 'g');
      linkedText = linkedText.replace(regex, (match, offset, string) => {
        const openBrackets = (string.substring(0, offset).match(/</g) || []).length;
        const closeBrackets = (string.substring(0, offset).match(/>/g) || []).length;
        if (openBrackets > closeBrackets) {
          return match;
        }
        return `<${rawUrl}|${match}>`;
      });
    }
  });

  // 3. Final pass to eliminate nested bracket pairs
  linkedText = linkedText.replace(/<(https?:\/\/[^|>]+)\|<(https?:\/\/[^|>]+)\|([^>]+)>>/g, '<$1|$3>');
  return linkedText;
}

const outputs = [];

// 1. Weekly Network Digest Summary (Priority #1)
if (digestSummary && (digestSummary.overview || (Array.isArray(digestSummary.bulletpoints) && digestSummary.bulletpoints.length > 0))) {
  let msg = '';
  if (greeting) msg += `${greeting}\n\n`;
  msg += `📊 *1. Weekly Network Digest Summary* 📊\n`;
  if (digestSummary.overview) msg += `${digestSummary.overview}\n\n`;
  if (Array.isArray(digestSummary.bulletpoints)) {
    digestSummary.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 2. New Persons & Associated Companies Highlights (Priority #2)
if (newPersons && (newPersons.overview || (Array.isArray(newPersons.bulletpoints) && newPersons.bulletpoints.length > 0))) {
  let msg = `👥 *2. New Persons & Associated Companies* 👥\n`;
  if (newPersons.overview) msg += `${newPersons.overview}\n\n`;
  if (Array.isArray(newPersons.bulletpoints)) {
    newPersons.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 3. Recent Activities & Outreach Review (Priority #3)
if (activitiesReview && (activitiesReview.overview || (Array.isArray(activitiesReview.bulletpoints) && activitiesReview.bulletpoints.length > 0))) {
  let msg = `🤝 *3. Recent Activities & Outreach Review* 🤝\n`;
  if (activitiesReview.overview) msg += `${activitiesReview.overview}\n\n`;
  if (Array.isArray(activitiesReview.bulletpoints)) {
    activitiesReview.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 4. Recommended Follow-Up Actions for Don Jimmy (Priority #4)
if (recommendedActions.length > 0) {
  let msg = `💡 *4. Recommended Follow-Up Actions for Don Jimmy* 💡\n`;
  recommendedActions.forEach(step => { msg += `• ${step}\n`; });
  if (signoff) msg += `\n${signoff}`;
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
} else if (signoff) {
  outputs.push({ json: { response: addSlackLinks(signoff) } });
}

return outputs;
